"""Generate readable standalone Vega-Lite specifications."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'charts'
OUT.mkdir(exist_ok=True)
TEAL, CORAL = '#23776f', '#c5633f'
config = {'background': '#faf8f2', 'font': 'Arial', 'view': {'stroke': None}, 'axis': {'labelColor': '#4d5c5a', 'titleColor': '#263e3b', 'gridColor': '#e3e5dd', 'domain': False, 'labelFontSize': 11, 'titleFontSize': 12, 'titlePadding': 12}, 'legend': {'orient': 'bottom', 'title': None, 'labelFontSize': 11}, 'range': {'category': [TEAL, CORAL, '#a99b65', '#617c93']}}

def field(name, kind='quantitative', **kw): return {'field': name, 'type': kind, **kw}
def save(name, data, spec):
    numeric = {'workforce.csv': ['year', 'teacher_fte', 'student_fte'], 'ratios.csv': ['year', 'ratio'], 'age.csv': ['year', 'percent', 'table'], 'working_hours.csv': ['year', 'hours', 'table'], 'leaving_reasons.csv': ['year', 'percent', 'table'], 'employment.csv':['year','percent'], 'experience.csv':['year','percent','table'],'gender.csv':['year','percent','table']}[data]
    result = {'$schema': 'https://vega.github.io/schema/vega-lite/v5.json', 'width': 'container', 'height': 290, 'data': {'url': f'data/processed/{data}', 'format': {'type': 'csv', 'parse': {key: 'number' for key in numeric}}}, **spec, 'config': config}
    (OUT / f'{name}.json').write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')

national = "datum.state === 'Australia'"
year = field('year', axis={'format': 'd', 'tickCount': 6}, scale={'zero': False}, title='Year')
save('01-teacher-trends', 'workforce.csv', {'transform': [{'filter': national + " && datum.sector !== 'All sectors'"}], 'mark': {'type': 'line', 'strokeWidth': 3, 'point': {'size': 20}}, 'encoding': {'x': year, 'y': field('teacher_fte', title='Teaching staff (FTE)', axis={'format': '~s'}), 'color': field('sector', 'nominal'), 'tooltip': [field('year', format='d'), field('sector', 'nominal'), field('teacher_fte', format=',.1f', title='Teacher FTE')]}})
save('02-indexed-growth', 'workforce.csv', {'transform': [{'filter': national + " && datum.sector === 'All sectors'"}, {'fold': ['teacher_fte', 'student_fte'], 'as': ['measure', 'value']}, {'joinaggregate': [{'op': 'argmin', 'field': 'year', 'as': 'base'}], 'groupby': ['measure']}, {'calculate': 'datum.value / datum.base.value * 100', 'as': 'index'}, {'calculate': "datum.measure === 'teacher_fte' ? 'Teaching staff' : 'Students'", 'as': 'series'}], 'mark': {'type': 'line', 'strokeWidth': 3}, 'encoding': {'x': year, 'y': field('index', title='Index (2006 = 100)', scale={'domain': [95, 140], 'zero': False}), 'color': field('series', 'nominal'), 'tooltip': [field('year', format='d'), field('series', 'nominal'), field('index', format='.1f')]}})
save('03-sector-shares', 'workforce.csv', {'transform': [{'filter': national + " && datum.sector !== 'All sectors'"}], 'mark': 'area', 'encoding': {'x': year, 'y': field('teacher_fte', stack='normalize', title='Share of teacher FTE', axis={'format': '.0%'}), 'color': field('sector', 'nominal'), 'tooltip': [field('year', format='d'), field('sector', 'nominal'), field('teacher_fte', format=',.1f')]}})
save('04-ratio-heatmap', 'ratios.csv', {'height': 270, 'transform': [{'filter': "datum.state !== 'Australia' && datum.sector === 'All sectors' && datum.level === 'All Levels'"}], 'mark': {'type': 'rect', 'stroke': '#faf8f2', 'strokeWidth': 1}, 'encoding': {'x': field('year', 'ordinal', axis={'labelAngle': -45}, title='Year'), 'y': field('state', 'nominal', sort=['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'], title=None), 'color': field('ratio', title='Students per teacher FTE', scale={'scheme': 'tealblues', 'zero': False}), 'tooltip': [field('state', 'nominal'), field('year', format='d'), field('ratio', format='.1f', title='Students per teacher FTE')]}})
save('05-sector-gap', 'ratios.csv', {'transform': [{'filter': "datum.year === 2025 && datum.state !== 'Australia' && datum.level === 'All Levels' && (datum.sector === 'Government' || datum.sector === 'Non-Government')"}], 'encoding': {'y': field('state', 'nominal', title=None), 'x': field('ratio', title='Students per teacher FTE', scale={'domain': [0, 16]}), 'tooltip': [field('state', 'nominal'), field('sector', 'nominal'), field('ratio', format='.1f')]}, 'layer': [{'mark': {'type': 'line', 'color': '#b6c3be', 'strokeWidth': 3}, 'encoding': {'detail': field('state', 'nominal')}}, {'mark': {'type': 'point', 'filled': True, 'size': 110}, 'encoding': {'color': field('sector', 'nominal')}}]})
save('06-age-profile', 'age.csv', {'mark': {'type': 'line', 'point': True, 'strokeWidth': 3}, 'encoding': {'x': field('age', 'ordinal', sort=['≤29', '30-39', '40-49', '50-59', '60-68', '69+'], title='Age group', axis={'labelAngle': 0}), 'y': field('percent', title='Share of subgroup (%)', scale={'domain': [0, 35]}), 'color': field('group', 'nominal'), 'tooltip': [field('group', 'nominal'), field('age', 'ordinal'), field('percent', format='.0f', title='Reported share (%)')]}})
save('07-hours-interval', 'working_hours.csv', {'height': 220, 'transform': [{'filter': 'datum.year === 2024'}, {'pivot': 'statistic', 'value': 'hours', 'groupby': ['school']}], 'encoding': {'y': field('school', 'nominal', title=None), 'x': field('25th percentile', title='Weekly working hours during term', scale={'domain': [0, 80]}), 'tooltip': [field('school', 'nominal'), field('5th percentile'), field('25th percentile'), field('Median'), field('75th percentile'), field('95th percentile')]}, 'layer': [{'mark': {'type': 'rule', 'color': '#a7b9b2'}, 'encoding': {'x': field('5th percentile'), 'x2': {'field': '95th percentile'}}}, {'mark': {'type': 'bar', 'color': TEAL, 'size': 22}, 'encoding': {'x2': {'field': '75th percentile'}}}, {'mark': {'type': 'tick', 'color': '#faf8f2', 'size': 22, 'thickness': 3}, 'encoding': {'x': field('Median')}}]})
save('08-leaving-reasons', 'leaving_reasons.csv', {'height': 390, 'transform': [{'filter': 'datum.year === 2024'}], 'mark': {'type': 'bar', 'color': CORAL}, 'encoding': {'x': field('percent', title='Share selecting reason (%)', scale={'domain': [0, 100]}), 'y': field('reason', 'nominal', sort='-x', title=None, axis={'labelLimit': 190}), 'tooltip': [field('reason', 'nominal'), field('percent', format='.0f', title='Share selecting reason (%)')]}})
save('12-employment-waffle','employment.csv',{'height':160,'transform':[{'calculate':"datum.arrangement === 'Permanent' ? 0 : datum.arrangement === 'Casual' ? 1 : 2",'as':'order'},{'window':[{'op':'sum','field':'percent','as':'end'}],'sort':[{'field':'order','order':'ascending'}],'frame':[None,0]},{'calculate':'sequence(datum.end - datum.percent, datum.end)','as':'cells'},{'flatten':['cells']},{'calculate':'datum.cells % 20','as':'column'},{'calculate':'floor(datum.cells / 20)','as':'row'}],'mark':{'type':'rect','stroke':'#faf8f2','strokeWidth':3},'encoding':{'x':field('column','ordinal',axis=None),'y':field('row','ordinal',axis=None),'color':field('arrangement','nominal',scale={'domain':['Permanent','Casual','Fixed-term'],'range':[TEAL,CORAL,'#a99b65']}),'tooltip':[field('arrangement','nominal'),field('percent',title='Share of workforce (%)')]}})
save('13-experience-pyramid','experience.csv',{'height':280,'transform':[{'filter':"datum.group !== 'Teacher workforce, overall'"},{'calculate':"datum.group === 'School classroom teachers' ? -datum.percent : datum.percent",'as':'side'}],'mark':{'type':'bar','size':26},'encoding':{'x':field('side',title='Share within subgroup (%)',scale={'domain':[-35,35]},axis={'labelExpr':'abs(datum.value)'}),'y':field('experience','ordinal',sort=['1-5 years','6-9 years','10-19 years','20-29 years','30-39 years','40+ years'],title='Teaching experience'),'color':field('group','nominal'),'tooltip':[field('group','nominal'),field('experience','ordinal'),field('percent',title='Share of subgroup (%)')]}})
save('14-pressure-slope','leaving_reasons.csv',{'height':330,'transform':[{'filter':"(datum.year === 2020 || datum.year === 2024) && (datum.reason === 'Workload' || datum.reason === 'Insufficient pay' || datum.reason === 'Student behaviour' || datum.reason === 'Class size')"}],'mark':{'type':'line','point':{'filled':True,'size':70},'strokeWidth':3},'encoding':{'x':field('year','ordinal',axis={'labelAngle':0},title=None),'y':field('percent',title='Share selecting reason (%)',scale={'domain':[0,100]}),'color':field('reason','nominal'),'tooltip':[field('reason','nominal'),field('year',format='d'),field('percent',title='Share selecting reason (%)')]}})
save('16-gender-profile','gender.csv',{'height':180,'encoding':{'x':field('percent',title='Women within subgroup (%)',scale={'domain':[0,100]}),'y':field('group','nominal',title=None,axis={'labelLimit':190}),'tooltip':[field('group','nominal'),field('percent',title='Women (%)')]},'layer':[{'mark':{'type':'rule','color':'#c9d6cd','strokeWidth':3},'encoding':{'x2':{'value':0}}},{'mark':{'type':'point','filled':True,'color':TEAL,'size':130}}]})

# Geographic maps use the same Australian Albers conic equal-area projection.
geo={'url':'data/geo/abs_states.geojson','format':{'type':'json','property':'features'}}
projection={'type':'conicEqualArea','rotate':[-132,0,0],'parallels':[-18,-36],'center':[0,-27]}
params=[{'name':'mapYear','value':2025},{'name':'mapSector','value':'All sectors'},{'name':'selectedState','value':'All states'}]
state_opacity={'condition':{'test':"selectedState === 'All states' || datum.properties.state === selectedState",'value':1},'value':0.2}
ratio_lookup={'lookup':'properties.state','from':{'data':{'url':'data/processed/map_values.csv','format':{'type':'csv','parse':{'ratio':'number','teacher_fte':'number','year':'number'}}},'key':'key','fields':['ratio']}}
# Composite keys permit dynamic year/sector filtering without duplicate joins.
lookup_transform=[{'calculate':"datum.properties.state + '|' + mapYear + '|' + mapSector",'as':'joinKey'},{'lookup':'joinKey','from':{'data':{'url':'data/processed/map_values.csv','format':{'type':'csv','parse':{'ratio':'number','teacher_fte':'number','year':'number'}}},'key':'key','fields':['ratio','teacher_fte']}}]
labels={'data':{'url':'data/processed/state_points.csv','format':{'type':'csv','parse':{'longitude':'number','latitude':'number'}}},'mark':{'type':'text','fontSize':11,'fontWeight':'bold','dy':-10,'stroke':'#faf8f2','strokeWidth':2},'encoding':{'longitude':field('longitude'),'latitude':field('latitude'),'text':field('state','nominal')}}
for name,body in [
 ('09-ratio-choropleth',{'data':geo,'transform':lookup_transform,'layer':[{'mark':{'type':'geoshape','stroke':'#faf8f2','strokeWidth':1},'encoding':{'color':field('ratio',scale={'domain':[9,16],'scheme':'tealblues'},legend={'title':'Students per teacher FTE'}),'opacity':state_opacity,'tooltip':[field('properties.state','nominal',title='State'),field('ratio',format='.1f',title='Students per teacher FTE')]}},labels]}),
 ('10-teacher-symbols',{'layer':[{'data':geo,'mark':{'type':'geoshape','fill':'#e2e7dc','stroke':'#faf8f2'}},{'data':{'url':'data/processed/state_points.csv','format':{'type':'csv','parse':{'longitude':'number','latitude':'number'}}},'transform':[{'calculate':"datum.state + '|' + mapYear + '|' + mapSector",'as':'joinKey'},{'lookup':'joinKey','from':{'data':{'url':'data/processed/map_values.csv','format':{'type':'csv','parse':{'teacher_fte':'number'}}},'key':'key','fields':['teacher_fte']}}],'mark':{'type':'circle','color':CORAL,'stroke':'#faf8f2','strokeWidth':1.5},'encoding':{'longitude':field('longitude'),'latitude':field('latitude'),'size':field('teacher_fte',scale={'domain':[0,100000],'range':[0,4500]},legend={'title':'Teacher FTE','values':[10000,50000,100000],'format':'~s'}),'opacity':{'condition':{'test':"selectedState === 'All states' || datum.state === selectedState",'value':0.8},'value':0.15},'tooltip':[field('state','nominal'),field('teacher_fte',format=',.1f',title='Teacher FTE')]}},labels]})]:
    spec={'$schema':'https://vega.github.io/schema/vega-lite/v5.json','width':'container','height':440,'params':params,'projection':projection,**body,'config':config}
    (OUT/(name+'.json')).write_text(json.dumps(spec,indent=2)+'\n',encoding='utf-8')

cartogram={'$schema':'https://vega.github.io/schema/vega/v5.json','description':'Non-contiguous area cartogram: each state silhouette has area proportional to 2025 all-sector teacher FTE. Positions are schematic, not school locations.','width':760,'height':520,'padding':5,'background':'#faf8f2','signals':[{'name':'selectedState','value':'All states'},{'name':'factor','update':'width / 760'}],'data':[{'name':'states','url':'data/geo/teacher_cartogram.json'}],'marks':[{'type':'path','from':{'data':'states'},'encode':{'update':{'path':{'field':'path'},'x':{'signal':'datum.x * factor'},'y':{'signal':'datum.y * factor'},'scaleX':{'signal':'factor'},'scaleY':{'signal':'factor'},'fill':{'value':TEAL},'fillOpacity':{'signal':"selectedState === 'All states' || datum.state === selectedState ? 0.85 : 0.2"},'stroke':{'value':'#faf8f2'},'strokeWidth':{'value':1},'tooltip':{'signal':"{'State':datum.state,'Year':2025,'Teacher FTE':format(datum.teacher_fte,',.1f')}"}}}},{'type':'text','from':{'data':'states'},'encode':{'update':{'x':{'signal':'datum.x * factor'},'y':{'signal':'datum.y * factor'},'text':{'field':'state'},'align':{'value':'center'},'baseline':{'value':'middle'},'fill':{'value':'#263e3b'},'stroke':{'value':'#faf8f2'},'strokeWidth':{'value':2},'fontSize':{'value':12},'fontWeight':{'value':'bold'}}}}]}
(OUT/'11-area-cartogram.json').write_text(json.dumps(cartogram,indent=2)+'\n',encoding='utf-8')

treemap={'$schema':'https://vega.github.io/schema/vega/v5.json','description':'Teaching staff FTE by state and school sector, 2025; area is proportional to FTE.','width':760,'height':390,'padding':3,'background':'#faf8f2','signals':[{'name':'selectedState','value':'All states'}],'data':[{'name':'tree','url':'data/processed/workforce.csv','format':{'type':'csv','parse':{'year':'number','teacher_fte':'number'}},'transform':[{'type':'filter','expr':"datum.year === 2025 && datum.state !== 'Australia' && datum.sector !== 'All sectors'"},{'type':'nest','keys':['state','sector']},{'type':'treemap','field':'teacher_fte','sort':{'field':'value','order':'descending'},'round':False,'method':'squarify','size':[{'signal':'width'},{'signal':'height'}],'paddingInner':2,'paddingOuter':1}]},{'name':'leaves','source':'tree','transform':[{'type':'filter','expr':'!datum.children'}]}],'scales':[{'name':'colour','type':'ordinal','domain':['Government','Catholic','Independent'],'range':[TEAL,CORAL,'#a99b65']}],'legends':[{'fill':'colour','orient':'bottom','direction':'horizontal','labelFontSize':11}],'marks':[{'type':'rect','from':{'data':'leaves'},'encode':{'update':{'x':{'field':'x0'},'y':{'field':'y0'},'x2':{'field':'x1'},'y2':{'field':'y1'},'fill':{'scale':'colour','field':'sector'},'opacity':{'signal':"selectedState === 'All states' || datum.state === selectedState ? 1 : 0.2"},'tooltip':{'signal':"{'State':datum.state,'Sector':datum.sector,'Teacher FTE':format(datum.teacher_fte,',.1f')}"}}}},{'type':'text','from':{'data':'leaves'},'encode':{'update':{'x':{'signal':'(datum.x0+datum.x1)/2'},'y':{'signal':'(datum.y0+datum.y1)/2'},'text':{'signal':"datum.x1-datum.x0 > 38 && datum.y1-datum.y0 > 22 ? datum.state : ''"},'align':{'value':'center'},'baseline':{'value':'middle'},'fontSize':{'value':11},'fill':{'value':'white'}}}}]}
(OUT/'15-sector-treemap.json').write_text(json.dumps(treemap,indent=2)+'\n',encoding='utf-8')
# Keep category colours stable across chapters and idioms.
for name in ['01-teacher-trends','03-sector-shares']:
    file=OUT/(name+'.json');spec=json.loads(file.read_text(encoding='utf-8'))
    spec['encoding']['color']['scale']={'domain':['Government','Catholic','Independent'],'range':[TEAL,CORAL,'#a99b65']}
    file.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
for name in ['06-age-profile','13-experience-pyramid']:
    file=OUT/(name+'.json');spec=json.loads(file.read_text(encoding='utf-8'))
    spec['encoding']['color']['scale']={'domain':['School classroom teachers','Casual relief teachers'],'range':[TEAL,CORAL]}
    file.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
file=OUT/'02-indexed-growth.json';spec=json.loads(file.read_text(encoding='utf-8'))
spec['encoding']['color']['scale']={'domain':['Teaching staff','Students'],'range':[TEAL,CORAL]}
spec['transform'].append({'calculate':"datum.series + ' +' + format(datum.index - 100, '.1f') + '%'",'as':'growthLabel'})
spec.pop('mark')
spec['layer']=[{'mark':{'type':'line','strokeWidth':3}},{'transform':[{'filter':'datum.year === 2025'}],'mark':{'type':'text','align':'right','dx':-6,'dy':-13,'fontSize':12,'fontWeight':'bold'},'encoding':{'text':field('growthLabel','nominal')}}]
file.write_text(json.dumps(spec,indent=2)+'\n',encoding='utf-8')
file=OUT/'09-ratio-choropleth.json';spec=json.loads(file.read_text(encoding='utf-8'))
spec['layer'][0]['encoding']['color']['scale']['domain']=[10,17]
spec['transform'].extend([{'calculate':'toNumber(datum.ratio)','as':'ratio'},{'calculate':'toNumber(datum.teacher_fte)','as':'teacher_fte'}])
file.write_text(json.dumps(spec,indent=2)+'\n',encoding='utf-8')
file=OUT/'10-teacher-symbols.json';spec=json.loads(file.read_text(encoding='utf-8'))
spec['layer'][1]['transform'].append({'calculate':'toNumber(datum.teacher_fte)','as':'teacher_fte'})
file.write_text(json.dumps(spec,indent=2)+'\n',encoding='utf-8')
from refine_charts import refine
refine(OUT)
print('Wrote', len(list(OUT.glob('*.json'))), 'chart specifications')
